            info(
                "profile source already uses ${mode} mode; reloading: "
                . $profile_name
            );
        }

        my $disable_link = "$profile_dir/disable/$profile_name";
        if (-l $disable_link) {
            unlink $disable_link ||
                fatal("cannot remove AppArmor disable entry: $disable_link");
        }
    }

